using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Reflection;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using Racer;using Object=UnityEngine.Object;
public static class ProtectCaveHillsideRoutes{
 public static string Main(){var road=Object.FindAnyObjectByType<RaceDirector>().road;road.Initialize();var samples=new List<Vector3>();for(float s=0;s<road.Length;s+=1)samples.Add(road.At(s,out _));var objects=new[]{GameObject.Find("Ground_Echo wooded hillside"),GameObject.Find("Echo eroded hillside face 0"),GameObject.Find("Echo eroded hillside face 140")};var surfaces=objects.Select(g=>g.GetComponent<Collider>()).ToArray();
 float Original(Vector3 p)=>Physics.RaycastAll(new(p.x,200,p.z),Vector3.down,300,1,QueryTriggerInteraction.Ignore).Where(h=>h.collider.name.StartsWith("Ground_")&&!surfaces.Contains(h.collider)).Select(h=>h.point.y).DefaultIfEmpty(p.y).Max();int changed=0;
 foreach(var g in objects){var m=g.GetComponent<MeshFilter>().sharedMesh;var v=m.vertices;for(int i=0;i<v.Length;i++){var p=v[i];float d=samples.Min(q=>Vector2.Distance(new(q.x,q.z),new(p.x,p.z)));float blend=Mathf.SmoothStep(0,1,Mathf.InverseLerp(8,15,d));float y=Original(p)-.08f;if(blend<1&&p.y>y){p.y=Mathf.Lerp(y,p.y,blend);changed++;}if(g!=objects[0]&&i%5==0){p.y-=.65f;}v[i]=p;}m.vertices=v;m.RecalculateNormals();m.RecalculateBounds();EditorUtility.SetDirty(m);g.GetComponent<MeshCollider>().sharedMesh=null;g.GetComponent<MeshCollider>().sharedMesh=m;}
 Physics.SyncTransforms();var hill=surfaces[0];var trees=Object.FindObjectsByType<Collider>().Where(c=>c.name.ToLower().Contains("tree")||c.name.ToLower().Contains("trunk")).Where(c=>{var p=c.bounds.center;return surfaces.Any(s=>s.Raycast(new Ray(new(p.x,200,p.z),Vector3.down),out var h,300))&&Math.Abs(Racer.Editor.BackyardReverseAuthoring.Ground(p)-c.bounds.min.y)>.1f;}).ToArray();typeof(Racer.Editor.BackyardReverseAuthoring).GetMethod("Trees",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{(Func<Collider,bool>)(c=>false),(Func<Collider,bool>)(c=>trees.Contains(c))});
 EditorSceneManager.MarkSceneDirty(UnityEngine.SceneManagement.SceneManager.GetActiveScene());EditorSceneManager.SaveScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene());AssetDatabase.SaveAssets();File.WriteAllText("Docs/CaveHillside/route-protection.txt",$"Feathered {changed} cover vertices down to unchanged main-route terrain with 8m protected corridor and 15m blend; reseated {trees.Length} affected trees. Portal rock/earth joins overlap 0.65m.");return File.ReadAllText("Docs/CaveHillside/route-protection.txt");}
}
